const N=(tag,text)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;return e;};
const digest=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');
export function signingBundleButton({origin,token,session,context,beforeDownload=async()=>true}){
 const button=N('button','소장 서명용 4종 받기');button.type='button';button.className='signing-bundle-button';button.style.cssText='display:block;margin:6px 0;max-width:140px;white-space:normal;font-size:12px';let busy=false;
 button.onclick=async()=>{if(busy)return;busy=true;button.disabled=true;let note=button.nextElementSibling;if(!note?.classList.contains('signing-bundle-status')){note=N('span');note.className='signing-bundle-status';note.style.cssText='display:block;max-width:240px;font-size:12px;overflow-wrap:anywhere';note.setAttribute('role','status');button.after(note);}const old=button.textContent;
 const request=async(path,options={})=>{session();const r=await fetch(origin+path,{...options,cache:'no-store',headers:{Authorization:'Bearer '+token,...(options.body?{'Content-Type':'application/json'}:{})}});session();if(!r.ok){const value=await r.json().catch(()=>({}));throw Error(typeof value.detail==='string'&&/[가-힣]/.test(value.detail)?value.detail:'평가서를 받지 못했습니다. 다시 시도해 주세요.');}return r;};
 try{note.textContent='';if(!await beforeDownload())return;const c=context(),base='/safety-features/half-year-reviews/plans/'+encodeURIComponent(c.plan)+'/signature-bundle',query='?'+new URLSearchParams({period:c.period});button.textContent='평가내용 확인 중…';const prepared=await(await request(base+query)).json();if(prepared.eligible===false)throw Error('4종 평가를 모두 작성 완료한 뒤 다운로드해 주세요.');let allow=false;if(prepared.missing.length){const labels=prepared.missing.map(r=>r.label).join(', ');if(!confirm(labels+'이 아직입니다.\n다운로드 받으시겠습니까?'))return;allow=true;}let job=await(await request(base+query,{method:'POST',body:JSON.stringify({request_key:crypto.randomUUID(),fingerprint:prepared.fingerprint,allow_incomplete:allow})})).json();button.textContent='평가서 4종 만드는 중…';const deadline=Date.now()+180000;
 while(job.status!=='READY'){if(job.status==='FAILED')throw Error('평가서를 만들지 못했습니다. 다시 눌러 주세요.');if(Date.now()>deadline)throw Error('평가서 작성에 시간이 걸리고 있습니다. 잠시 후 다시 눌러 주세요.');await new Promise(r=>setTimeout(r,2000));session();job=await(await request(base+'/'+job.id+query)).json();}
 const raw=await(await request(base+'/'+job.id+'/file'+query)).arrayBuffer();session();const checksum=await digest(raw);session();if(raw.byteLength!==job.result.bytes||checksum!==job.result.sha256)throw Error('받은 파일을 확인하지 못했습니다. 다시 눌러 주세요.');const url=URL.createObjectURL(new Blob([raw],{type:'application/pdf'})),a=N('a');a.href=url;a.download=job.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);note.textContent='서명용 4종을 받았습니다. 서명 요청은 '+(prepared.request_on?prepared.request_on+'(월)':'월요일')+'에 공무에게 전송해 주세요.';
 }catch(e){note.textContent=/[가-힣]/.test(e.message)?e.message:'평가서를 받지 못했습니다. 인터넷 연결을 확인해 주세요.';}finally{busy=false;button.disabled=false;button.textContent=old;}};return button;
}
